// Champs ajoutés aux dossiers patient (Basique 25, Avancé 3, Mise à jour 26) : nom en trois parties, type de téléphone, et pour chaque champ d'historique
// à choix par défaut les choix cochés (`…Presets`) et le texte libre (`…Free`) qui composent le texte regroupé.
const PATIENT_FILE_EXTRA = ['patientZIP', 'patientFirstName', 'patientMiddleName', 'patientLastName'];
const PATIENT_FILE_UPDATE_EXTRA = [
    'patientZIPNew',
    'patientFirstNameNew', 'patientMiddleNameNew', 'patientLastNameNew', 'patientPHNew', 'patientDiscordNew', 'patientRaceNew', 'patientAddressNew',
    'patientGenderNew', 'patientTitleNew', 'patientNameNew', 'patientDateOfBirthNew',
];
const withPresetFields = (fields) => [...fields, ...Object.keys(HISTORY_PRESETS).flatMap((key) => [`${key}Presets`, `${key}Free`])];

// Champs ajoutés aux rapports de médecine légale : nom du défunt (et du témoin) en trois parties, ville du lieu, agence du demandeur, coordonnées du coroner,
// causes à choix (`…Presets` / `…Free`).
const DMEC_EXTRA = {
    1: ['decedentFirstName', 'decedentMiddleName', 'decedentLastName', 'placeOfDeathZip', 'requestingAgency', 'probableCauseOfDeathPresets', 'probableCauseOfDeathFree', 'massFatality'],
    2: ['decedentFirstName', 'decedentMiddleName', 'decedentLastName', 'decedentName', 'decedentOOC', 'patientID', 'coronerEmail', 'coronerPHNumber', 'reportDecedentNames', 'reportDecedentOOC'],
    4: ['placeOfDeath', 'placeOfDeathZip', 'decedentFirstName', 'decedentMiddleName', 'decedentLastName', 'causeOfDeathPresets', 'causeOfDeathFree', 'deathType', 'autopsyDeathCauses', 'autopsyAnatomicSummaryItems'],
    8: ['decedentFirstName', 'decedentMiddleName', 'decedentLastName', 'witnessFirstName', 'witnessMiddleName', 'witnessLastName', 'patientID', 'placeOfDeath', 'placeOfDeathZip', 'probableCauseOfDeathPresets', 'probableCauseOfDeathFree'],
    11: ['placeOfDeathZip', 'requestingAgency', 'decedents'],
    37: ['decedentFirstName', 'decedentMiddleName', 'decedentLastName', 'placeOfDeathZip', 'causesOfDeath', 'causesOfDeathPresets', 'causesOfDeathFree'],
};

const getRelevantFields = (bbCodeVersion) => {
    const base = baseRelevantFields(bbCodeVersion);
    if (DMEC_EXTRA[bbCodeVersion]) return [...new Set([...base, ...DMEC_EXTRA[bbCodeVersion], 'coronerPHNumber', 'coronerEmail'])];
    if (bbCodeVersion === 3 || bbCodeVersion === 25) return [...new Set(withPresetFields([...base, ...PATIENT_FILE_EXTRA]))];
    // Mise à jour : toutes les rubriques du dossier avancé peuvent être modifiées, donc tous leurs champs sont gardés.
    if (bbCodeVersion === 26) return [...new Set(withPresetFields([...baseRelevantFields(3), ...base, ...PATIENT_FILE_EXTRA, ...PATIENT_FILE_UPDATE_EXTRA]))];
    return base;
};

export default getRelevantFields;